function _rawT(key){
  const lang = (typeof state!=='undefined' && state.settings && state.settings.language) || 'el';
  return (I18N[lang] && I18N[lang][key]) ?? (I18N.el[key] ?? key);
}
// {clients} {client} {sessions} {session} are the words of the person's
// specialty — "πελάτες / ραντεβού" by default, "μαθητές / μαθήματα" for a
// tutor — so no message speaks of students to a physiotherapist. {Sessions}
// with a capital asks for a capital. A value the caller passes to tf() wins:
// this only fills what is left.
function _labelT(str){
  if(typeof str !== 'string' || !/\{([Cc]lients?|[Ss]essions?)\}/.test(str) || typeof getLabels !== 'function') return str;
  const lang = curLang(), L = getLabels(), lc = (x) => String(x || '').toLocaleLowerCase(lang);
  return str.replace(/\{([Cc]lients?|[Ss]essions?)\}/g, (m, w) => {
    const v = lc(L[w.toLowerCase()]);
    return w[0] === w[0].toUpperCase() ? v.charAt(0).toLocaleUpperCase(lang) + v.slice(1) : v;
  });
}
function t(key){ return _labelT(_rawT(key)); }
function curLang(){
  return (typeof state!=='undefined' && state.settings && state.settings.language) || 'el';
}
// t() with {placeholder} substitution, e.g. tf('confirm_delete_client_title',{client:'Maria'})
function tf(key, params){
  let str = _rawT(key);
  if(params) for(const k in params) str = str.split('{'+k+'}').join(params[k]);
  return _labelT(str);
}

const DAYS = ['','Δευ','Τρί','Τετ','Πέμ','Παρ','Σάβ','Κυρ'];
const DAYS_FULL = ['','Δευτέρα','Τρίτη','Τετάρτη','Πέμπτη','Παρασκευή','Σάββατο','Κυριακή'];
const COLORS = ['color-0','color-1','color-2','color-3','color-4','color-5','color-6','color-7','color-8','color-9'];
const SUBJECTS = ['Μαθηματικά','Φυσική','Χημεία','Βιολογία','Αγγλικά','Ιστορία','Γεωγραφία','Λογοτεχνία','Πληροφορική','Άλγεβρα','Γεωμετρία','Άλλο'];

// What each profession actually does, instead of a school subject list for
// everyone. A personal trainer offering "Χημεία" was the giveaway.
//
// Keys are stable identifiers, never display text, so switching UI language
// leaves stored records untouched. The tutor list keeps its original Greek
// keys so no existing student's subject changes meaning.
const PROFESSION_SUBJECTS = {
  tutor: SUBJECTS,
  physiotherapy: ['physio_rehab', 'physio_back', 'physio_sports', 'physio_post_op', 'physio_neuro', 'physio_manual', 'physio_resp', 'Άλλο'],
  massage: ['mass_relax', 'mass_deep', 'mass_sports', 'mass_lymph', 'mass_preg', 'mass_reflex', 'Άλλο'],
  beauty: ['beauty_facial', 'beauty_mani', 'beauty_pedi', 'beauty_wax', 'beauty_lash', 'beauty_makeup', 'beauty_hair', 'Άλλο'],
  personal_training: ['pt_strength', 'pt_cardio', 'pt_hiit', 'pt_mobility', 'pt_pilates', 'pt_yoga', 'pt_rehab', 'pt_assessment', 'Άλλο'],
  music: ['mus_piano', 'mus_guitar', 'mus_violin', 'mus_drums', 'mus_voice', 'mus_bass', 'mus_theory', 'Άλλο'],
  speech: ['sp_artic', 'sp_lang', 'sp_fluency', 'sp_voice', 'sp_swallow', 'sp_learning', 'Άλλο'],
  psychologist: ['psy_individual', 'psy_couple', 'psy_family', 'psy_child', 'psy_cbt', 'psy_assessment', 'Άλλο'],
  cleaning: ['cl_general', 'cl_deep', 'cl_windows', 'cl_move', 'cl_office', 'cl_ironing', 'Άλλο'],
  pet: ['pet_walk', 'pet_groom', 'pet_train', 'pet_sit', 'pet_vet', 'Άλλο'],
  repair: ['rep_plumbing', 'rep_electrical', 'rep_appliance', 'rep_hvac', 'rep_carpentry', 'rep_paint', 'rep_it', 'Άλλο'],
  freelancer: ['gen_consult', 'gen_meeting', 'gen_service', 'gen_followup', 'Άλλο'],
  other: ['gen_consult', 'gen_meeting', 'gen_service', 'gen_followup', 'Άλλο'],
};

// The list for the profession in use, falling back to the tutor list.
function getSubjects(){
  const p = (typeof state!=='undefined' && state.settings && state.settings.profession) || 'other';
  return PROFESSION_SUBJECTS[p] || SUBJECTS;
}

// Mutate DAYS/DAYS_FULL in place (they're `const` arrays referenced by index
// throughout the app) so every existing DAYS[d] call site picks up the current
// language without having to be rewritten.
function applyLanguageArrays(){
  const lang = curLang();
  const d = (I18N[lang]&&I18N[lang].days) || I18N.el.days;
  const df = (I18N[lang]&&I18N[lang].daysFull) || I18N.el.daysFull;
  for(let i=0;i<8;i++){ DAYS[i]=d[i] || DAYS[i]; DAYS_FULL[i]=df[i] || DAYS_FULL[i]; }
}

// Students' `subject` field is always stored as one of the fixed Greek
// SUBJECTS values (the <select> in the student form never lets free text
// through), so switching UI language only needs to translate it for display
// — the stored value never changes, so existing student data never migrates.
// What a client does, as shown under their name: the current profession's
// own word for it, the person's own typed words, or nothing. Never another
// profession's word (a tutor's pupil labelled "Consultation" because they
// were added before the profession was chosen), and never a guess.
function subjectText(subj){
  if(!subj || subj === '—' || subj === 'Άλλο') return '';
  if(getSubjects().includes(subj)) return subjectLabel(subj);
  const known = Object.values(PROFESSION_SUBJECTS).some(l => l.includes(subj));
  return known ? '' : String(subj);
}
function subjectLabel(subj){
  const lang = curLang();
  const map = (I18N[lang]&&I18N[lang].subjects) || I18N.el.subjects;
  return (map && map[subj]) || subj;
}

